import { Component, Vue } from 'vue-property-decorator';
import { OverlaysEventEmitter } from '../../event-emitter';

@Component({
    name: 'Toast'
})
export default class Toast extends Vue {
    public title: string = '';
    public message: string = '';
    public isVisible: boolean = false;
    public timeoutId: number;

    public created() {
        this.show = this.show.bind(this);
        this.hide = this.hide.bind(this);
    }

    public mounted() {
        OverlaysEventEmitter.on('showToast', this.show);
    }

    public beforeDestroy() {
        OverlaysEventEmitter.off('showToast', this.show);
    }

    private show(title: string, message: string, duration: number = 5000) {
        if (this.timeoutId) {
            window.clearTimeout(this.timeoutId);
        }

        this.title = title;
        this.message = message;
        this.isVisible = true;
        this.timeoutId = window.setTimeout(() => this.hide(), duration);
    }

    private hide() {
        this.title = '';
        this.message = '';
        this.isVisible = false;
    }
}
